class Solution(object):
    def minDeletion(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        n = len(nums)
        ans = 0
        for i in range(n):
            if (i - ans) % 2 == 0 and i + 1 < n and nums[i] == nums[i + 1]:
                ans += 1
        if (n - ans) % 2 != 0:
            ans += 1
        return ans
